import { shelterProjects, observatoryProjects } from './haven-content.js';
// Teaching, shared work, and observation extend the same learning trail.
import { clockProjects, discoveryProjects } from './clockwork-content.js';
export const apprentices = [
  {id:'nell',name:'Nell',place:'The reading table',look:{hair:'braid',outfit:'moss',scarf:'cream',accessory:'none'},story:'Nell carried the library’s rescued borrowing cards downstairs. She knows every reader by name, but worries that one wrong line might spoil the whole catalogue.',voices:['“Could we try a very small example together?”','“I tried another name on my own. It worked!”','“Now I know why a missing book needs a different answer.”','“I can explain my work to the next reader. Would you listen?”']},
  {id:'kit',name:'Kit',place:'The kitchen bench',look:{hair:'waves',outfit:'rust',scarf:'sage',accessory:'none'},story:'Kit helps Rowan prepare the morning trays. They have plenty of ideas and a habit of rushing the last step. You can make room for mistakes over a warm cup of tea.',voices:['“Mine nearly works. That counts as a start, doesn’t it?”','“I checked two trays instead of guessing. Much better.”','“The empty list was the example I kept forgetting.”','“I tested the rainy mornings too. The answer is less certain than I thought.”']}
];
const teaching=(id,npc,requires,title,lesson,bug,question,choices,answer,feedback,example,examples,exampleAnswer,exampleFeedback,task,solution,checks)=>({
  id,kind:'teaching',npc,requires,title,lesson,starter:bug,question,choices,answer,feedback,example,examples,exampleAnswer,exampleFeedback,task,solution,checks,
  xp:100+requires*5,coins:45+requires*2,hint:'Read the explanation and the chosen test example again. Follow one input through each line before changing it.'
});
export const teachingProjects=[
  teaching('nell-label','nell',0,'A name on a borrowing card',
    'Nell’s first function should return a greeting, so other tools can use it. print shows something on screen; return gives a value back to the caller.',
    'def greeting(name):\n    print("Hello, " + name + "!")',
    'Why does Nell’s caller receive None?',['The name is too short.','print displays text, but the function never returns the greeting.','Python cannot join strings.'],1,
    ['Name length is not involved. Try tracing what the caller receives.','Exactly. Printing and returning have different jobs.','Strings can be joined with +.'],
    'Which extra example checks that the function uses its input?',['greeting("Nell") again','greeting("Mira") should return "Hello, Mira!"','Only check whether Python starts'],1,
    ['A repeated example cannot catch a hard-coded name.','A different name exposes a hard-coded greeting.','Starting Python does not check the result.'],
    'Write greeting(name), returning "Hello, " followed by name and "!". Do not print instead of returning.',
    'def greeting(name):\n    return "Hello, " + name + "!"',
    'f=scope.get("greeting")\nassert callable(f)\nfor name in ["Nell","Mira","","June"]:\n    assert f(name)=="Hello, "+name+"!", "Return the greeting using the supplied name."'),
  teaching('kit-trays','kit',2,'Two trays, one small mistake',
    'Kit added the number of trays to the rolls on each tray. A useful explanation connects the operation to what is being counted.',
    'def roll_count(trays, per_tray):\n    return trays + per_tray',
    'How would you explain the fix?',['Add more comments.','Always return twelve.','Each tray contributes per_tray rolls, so multiply.'],2,
    ['Comments help readers, but do not change the calculation.','A fixed answer only works for one order.','Yes: three trays of four means 4 + 4 + 4.'],
    'Which example catches the addition bug?',['2 trays of 2: expect 4','3 trays of 4: expect 12','No example is needed'],1,
    ['Both addition and multiplication give 4 here.','3 + 4 is 7; 3 × 4 is 12. This distinguishes the two.','Try a case that could prove the code wrong.'],
    'Write roll_count(trays, per_tray). Return their product, including zero trays.',
    'def roll_count(trays, per_tray):\n    return trays * per_tray',
    'f=scope.get("roll_count")\nassert callable(f)\nfor a,b in [(3,4),(0,8),(5,1),(2,7)]:\n    assert f(a,b)==a*b, "Count all rolls, including a morning with no trays."'),
  teaching('nell-copies','nell',8,'The last copy on the shelf',
    'Nell wants a list of titles with at least one available copy. A zero means unavailable, not missing.',
    'def available(catalog):\n    return sorted(catalog)',
    'What does the current code forget?',['It includes titles even when their count is zero.','It should sort twice.','A dictionary cannot store counts.'],0,
    ['Right. Check the count before including the title.','Sorting changes order, not availability.','Dictionaries are well suited to title-to-count data.'],
    'Which catalogue reveals the mistake?',['{"Tea": 2}','{"Tea": 0, "Moss": 1}: expect ["Moss"]','An empty catalogue only'],1,
    ['The bug and the correct version agree here.','This checks both inclusion and exclusion.','Empty data matters, but alone cannot expose this bug.'],
    'Return sorted titles with count > 0 from available(catalog). Leave the catalogue unchanged.',
    'def available(catalog):\n    return sorted(title for title, count in catalog.items() if count > 0)',
    'f=scope.get("available")\nassert callable(f)\nfor c in [{},{"Tea":0,"Moss":1},{"B":2,"A":3},{"X":0}]:\n    before=c.copy()\n    assert f(c)==sorted(k for k,v in c.items() if v>0), "Only include available titles."\n    assert c==before, "Leave the catalogue unchanged."'),
  teaching('kit-total','kit',10,'Remember the empty basket',
    'Kit’s loop returns after its first item. Indentation decides which statements belong inside a loop.',
    'def basket_total(prices):\n    total = 0\n    for price in prices:\n        total += price\n        return total',
    'Where should the return belong?',['Before the loop.','After the loop, at the same indentation as total = 0.','Inside a second loop.'],1,
    ['That would return zero before counting anything.','Yes. Finish every item, then return the result.','One loop is enough.'],
    'Which pair of tests checks both problems?',['[2] and [3]','[2, 3] gives 5; [] gives 0','Only [0]'],1,
    ['One-item baskets hide the early return.','The first catches early return; the second catches an implicit None.','An empty basket is different from a basket containing zero.'],
    'Write basket_total(prices). Add all numbers and return 0 for an empty list.',
    'def basket_total(prices):\n    total = 0\n    for price in prices:\n        total += price\n    return total',
    'f=scope.get("basket_total")\nassert callable(f)\nfor p in [[],[2,3],[1.5,2.25,0],[0]]:\n    assert f(p)==sum(p), "Finish the whole basket, and return zero for an empty one."'),
  teaching('nell-missing','nell',16,'A blank card is not a zero',
    'Some recovered borrowing cards have no count yet. None means missing information; zero is a real observation. Nell wants the average of known counts.',
    'def known_average(values):\n    known = [v for v in values if v]\n    return sum(known) / len(known)',
    'Why does if v lose information?',['It removes zero along with None.','Zero is never useful.','Every missing value should become one.'],0,
    ['Exactly. Use v is not None to preserve observed zeros.','Zero is meaningful here: no copies available.','Inventing measurements changes the data.'],
    'Which example makes the distinction visible?',['[2, 4] gives 3','[0, None, 4] gives 2','[4] gives 4'],1,
    ['All entries are truthy, so both versions agree.','Keeping zero changes the denominator from one to two.','A single nonzero value hides the bug.'],
    'Return the average of non-None values. Return None when no known values remain. Keep zeros.',
    'def known_average(values):\n    known = [v for v in values if v is not None]\n    return sum(known) / len(known) if known else None',
    'f=scope.get("known_average")\nassert callable(f)\nfor values,expected in [([0,None,4],2),([],None),([None],None),([0,0],0),([2,5],3.5)]:\n    assert f(values)==expected, "Exclude None, preserve zero, and handle no known values."'),
  teaching('kit-evaluate','kit',24,'A prediction deserves a fair test',
    'Kit’s weather guesser was tested on the examples it had already seen. A separate set of labelled observations gives a more useful check. Accuracy is the fraction of predictions that match the truth.',
    'def accuracy(predicted, actual):\n    return 1.0',
    'How can Kit test fairly?',['Use the training labels as predictions.','Keep test observations separate and compare predictions with their labels.','Remove every wrong prediction.'],1,
    ['That copies the answers instead of testing predictions.','Yes. Keep test labels out of the prediction step.','Wrong predictions are exactly what evaluation must count.'],
    'Which test prevents a perfect-score shortcut?',['["sun"] vs ["sun"]','["sun", "rain"] vs ["rain", "rain"]: expect 0.5','Never test mistakes'],1,
    ['A constant 1.0 passes that single case.','One match out of two makes the shortcut fail.','A useful test includes wrong answers too.'],
    'Write accuracy(predicted, actual). Return matching pairs / length. Return None for two empty lists. Raise ValueError if lengths differ.',
    'def accuracy(predicted, actual):\n    if len(predicted) != len(actual):\n        raise ValueError("Lengths must match")\n    if not actual:\n        return None\n    return sum(p == a for p, a in zip(predicted, actual)) / len(actual)',
    'f=scope.get("accuracy")\nassert callable(f)\nfor p,a,e in [(["sun","rain"],["rain","rain"],0.5),([],[],None),(["x"],["y"],0),(["x"],["x"],1)]:\n    assert f(p,a)==e, "Compare every pair and handle empty data."\ntry:\n    f([1],[])\nexcept ValueError:\n    pass\nelse:\n    raise AssertionError("Reject unequal lengths.")')
];
const project=(id,kind,requires,title,task,starter,solution,checks,extra={})=>({id,kind,requires,title,task,starter,solution,checks,xp:220,coins:100,hint:'Start with a tiny input. Build one piece of the report at a time, then test an empty input.',...extra});
export const sharedProjects=[
  project('shared-herbs','shared',28,'June’s herbs, Mabel’s bread',
    'Write herb_order(recipe, stock, batches). Call your saved shopping_list(recipe, stock, batches). Return {"pick": missing, "total": sum of missing quantities}. Quantities are fictional bundles.',
    'def herb_order(recipe, stock, batches):\n    missing = shopping_list(recipe, stock, batches)\n    return {"pick": missing, "total": 0}',
    'def herb_order(recipe, stock, batches):\n    missing = shopping_list(recipe, stock, batches)\n    return {"pick": missing, "total": sum(missing.values())}',
    'f=scope.get("herb_order")\nassert callable(f)\nfor r,s,b in [({"sage":2,"mint":1},{"sage":1},3),({}, {},2),({"sage":2},{"sage":8},2)]:\n    wanted={k:max(v*b-s.get(k,0),0) for k,v in r.items() if v*b>s.get(k,0)}\n    assert f(r,s,b)=={"pick":wanted,"total":sum(wanted.values())}, "Use the saved shopping tool and total only shortages."',
    {tools:['bakery-shopping'],buildings:['bakery','greenhouse'],story:'June used to leave a basket of herbs beside Mabel’s oven every Friday. The first new basket should contain what the bakery needs, without taking every sprig from the greenhouse.',outcome:'A cloth-lined herb basket waits by the bakery. Rowan and Elio have a reason to cross the court together again.',demo:'herb_order({"sage": 2, "mint": 1}, {"sage": 1}, 3)'}),
  project('shared-books','shared',28,'A recipe travels with the basket',
    'Write recipe_delivery(catalog, requests). Clean every request with your saved clean_title, then pass the cleaned list to your saved lend_books. Return its report. Never change the catalogue.',
    'def recipe_delivery(catalog, requests):\n    cleaned = []\n    return lend_books(catalog, cleaned)',
    'def recipe_delivery(catalog, requests):\n    cleaned = [clean_title(title) for title in requests]\n    return lend_books(catalog, cleaned)',
    'f=scope.get("recipe_delivery")\nassert callable(f)\nc={"Herb Bread":1,"Tea":2};before=c.copy()\nassert f(c,[" herb bread ","HERB BREAD"," tea ","missing"])=={"stock":{"Herb Bread":0,"Tea":1},"served":["Herb Bread","Tea"],"waiting":["Herb Bread","Missing"]}, "Clean requests before lending; a second request must see remaining stock."\nassert c==before\nassert f({},[])=={"stock":{},"served":[],"waiting":[]}',
    {tools:['library-titles','library-loans'],buildings:['library','bakery','greenhouse'],previous:'shared-herbs',story:'Nell finds June’s margin notes in an old bread book. The library can lend recipes with the herb deliveries, but hurried handwriting must not promise the last copy twice.',outcome:'A recipe satchel joins the basket. Nell keeps a waiting list so the next neighbour gets their turn.',demo:'recipe_delivery({"Herb Bread": 1, "Tea": 2}, [" herb bread ", "HERB BREAD", " tea "])'}),
  project('shared-morning','shared',32,'One morning, many helping hands',
    'Write village_morning(orders, capacity, beds, target, catalog, requests). Call your saved plan_bakes, watering_plan, and lend_books. Return {"oven": baking report, "garden": deficits, "library": lending report}. Preserve all inputs.',
    'def village_morning(orders, capacity, beds, target, catalog, requests):\n    # The same data flows to three tools you already made.\n    return {}',
    'def village_morning(orders, capacity, beds, target, catalog, requests):\n    return {"oven": plan_bakes(orders, capacity),\n            "garden": watering_plan(beds, target),\n            "library": lend_books(catalog, requests)}',
    'import copy\nf=scope.get("village_morning")\nassert callable(f)\nfor args in [([["rye",3],["bun",2]],3,{"mint":0,"sage":None},20,{"Bread":1},["Bread","Bread"]),([],2,{},30,{},[])]:\n    before=copy.deepcopy(args)\n    o,c,b,t,books,req=args\n    expected={"oven":scope["plan_bakes"](o,c),"garden":scope["watering_plan"](b,t),"library":scope["lend_books"](books,req)}\n    assert f(*args)==expected, "Return all three reports under oven, garden, and library."\n    assert args==before, "Leave the shared records unchanged."',
    {tools:['bakery-planner','greenhouse-water','library-loans'],buildings:['bakery','greenhouse','library'],previous:'shared-books',story:'The three reopened doors now share a morning round. Kit takes the oven list, Elio checks the pots, and Nell packs the books. Your job is to join reliable tools without tangling their records.',outcome:'The morning round comes to life: bread, plants, and books, each with a clear place in a shared plan.',demo:'village_morning([["rye",3],["bun",2]], 3, {"mint":0,"sage":None}, 20, {"Bread":1}, ["Bread","Bread"])'})
];
export const lakeProjects=[
  project('lake-tally','lake',4,'Every cast belongs in the story',
    'Write tally(catches). Return a dictionary counting each outcome, including "No catch". An empty list returns {}.',
    'def tally(catches):\n    counts = {}\n    return counts',
    'def tally(catches):\n    counts = {}\n    for fish in catches:\n        counts[fish] = counts.get(fish, 0) + 1\n    return counts',
    'f=scope.get("tally")\nassert callable(f)\nfor c in [[],["Perch","No catch","Perch"],["Tench","Tench","Minnow"]]:\n    before=c.copy();expected={x:c.count(x) for x in set(c)}\n    assert f(c)==expected, "Count every outcome, including no catch."\n    assert c==before',
    {observations:6,story:'Elio keeps the quiet casts too. Leaving them out would make the lake seem far more generous than it is.',outcome:'Your journal can now count the days that stayed quiet as carefully as the bright little catches.'}),
  project('lake-frequency','lake',12,'What does often really mean?',
    'Write frequency(catches, species). Return the fraction equal to species, counting all casts in the denominator. Return None if there are no casts.',
    'def frequency(catches, species):\n    return 0',
    'def frequency(catches, species):\n    return catches.count(species) / len(catches) if catches else None',
    'f=scope.get("frequency")\nassert callable(f)\nfor c,s,e in [([], "Perch",None),(["Perch","No catch","Perch"],"Perch",2/3),(["Minnow"],"Perch",0),(["No catch"],"No catch",1)]:\n    got=f(c,s)\n    assert got is None if e is None else abs(got-e)<1e-9, "Divide matches by all casts, including no catch."',
    {observations:12,previous:'lake-tally',story:'A notebook of six sunny casts tells you about those six casts. It does not promise the next fish, or explain every rainy evening.',outcome:'You can describe what you observed as a frequency, without mistaking it for a promise.'}),
  project('lake-predict','lake',24,'A guess for a different morning',
    'Write predict_catch(rows, weather). rows are dictionaries with "weather" and "catch". Use the most common catch for matching weather; if none match, use all rows. Break ties alphabetically. Return None for no rows. Never change the rows.',
    'def predict_catch(rows, weather):\n    # Filter the training rows, count their outcomes, choose a winner.\n    return None',
    'def predict_catch(rows, weather):\n    matching = [r for r in rows if r["weather"] == weather]\n    sample = matching or rows\n    if not sample:\n        return None\n    counts = {}\n    for row in sample:\n        fish = row["catch"]\n        counts[fish] = counts.get(fish, 0) + 1\n    return min(counts, key=lambda fish: (-counts[fish], fish))',
    'import copy\nf=scope.get("predict_catch")\nassert callable(f)\nr=[{"weather":"sun","catch":"Perch"},{"weather":"rain","catch":"Tench"},{"weather":"rain","catch":"Tench"},{"weather":"sun","catch":"Minnow"}];before=copy.deepcopy(r)\nassert f(r,"rain")=="Tench"\nassert f(r,"sun")=="Minnow", "Break ties alphabetically."\nassert f(r,"cloud")=="Tench", "Use all training rows for unseen weather."\nassert f([],"sun") is None\nassert r==before',
    {observations:18,previous:'lake-frequency',story:'Kit joins you at the jetty. Together you will keep every fifth observation aside, train on the rest, and compare the guesser with a simple overall-most-common baseline.',outcome:'Your first lake model is ready for an honest test. Being wrong is useful evidence, too.'})
];
export const neighbourProjects=[...teachingProjects,...sharedProjects,...lakeProjects,...clockProjects,...discoveryProjects,...shelterProjects,...observatoryProjects];
export const neighbourProject=id=>neighbourProjects.find(p=>p.id===id);
